// ======================================================================= transport.rail (and vehicle.rail)
const RAIL = { category: 'transport.rail', tags: ['rail'] };
const GAUGE = 0.72, TRACK_L = 8, R = 24;
/** Track along +z, 8 m. `s` = 0 straight, ±1 curves (radius 24 m). Returns ballast, sleepers, rails. */
function trackShapes(s, w0) {
  const w = w0 || undefined;
  const at = (t) => { const f = t / R; return s ? { x: s * R * (1 - Math.cos(f)), z: -TRACK_L / 2 + R * Math.sin(f), h: s * f } : { x: 0, z: -TRACK_L / 2 + t, h: 0 }; };
  const out = [], n = 12, seg = s ? 4 : 1;
  for (let i = 0; i < seg; i++) { const a = at((i / seg) * TRACK_L), b = at(((i + 1) / seg) * TRACK_L);
    out.push(cbox([(a.x + b.x) / 2, 0.12, (a.z + b.z) / 2], [2.8, 0.24, Math.hypot(b.x - a.x, b.z - a.z) + 0.05], 'ballast', { yaw: Math.round(Math.atan2(b.x - a.x, b.z - a.z) * 1000) / 1000, collide: false, when: w }));
    for (const side of [-1, 1]) { const p = (q) => [q.x + side * GAUGE * Math.cos(q.h), 0.36, q.z - side * GAUGE * Math.sin(q.h)];
      out.push(bar(p(a), p(b), [0.07, 0.12], 'rail', { collide: false, when: w })); } }
  for (let i = 0; i < n; i++) { const q = at((i + 0.5) / n * TRACK_L); out.push(box([q.x, 0.27, q.z], [2.3, 0.1, 0.24], 'sleeper', { yaw: Math.round(q.h * 1000) / 1000, collide: false, when: w })); }
  return out;
}
